local Translate = ns.Lore.Translate

Translate("frFR", "ashenvale", {
	title = "Orneval",
	aliases = { "forêt d'Orneval" },
	sections = {
		{
			title = "Résumé",
			text = [=[Orneval est la grande forêt des {link:night-elves}elfes de la nuit{/link}, une terre d'arbres immenses, de lacs d'argent et de ruines blanches au nord de {link:kalimdor}Kalimdor{/link}. Elle s'étend de la mer grise de la {link:the-zoram-strand}grève de Zoram{/link}, à l'ouest, jusqu'au fleuve qui la sépare d'{link:azshara}Azshara{/link}, à l'est. {link:darkshore}Sombrivage{/link} et {link:felwood}Gangrebois{/link} se trouvent au nord, et les {link:stonetalon-mountains}Serres-Rocheuses{/link} et {link:the-barrens}les Tarides{/link} au sud. Pendant dix mille ans, les elfes de la nuit l'ont gardée comme un bois sacré. Elle n'est plus sacrée pour eux seuls. Les haches de la {link:horde}Horde{/link} résonnent dans ses vallées orientales, et la forêt est devenue le champ de bataille le plus ancien et le plus amer entre les elfes et les orcs.]=],
		},
		{
			title = "Origines",
			text = [=[Les arbres d'Orneval sont plus vieux que toute chronique. Avant la {link:great-sundering}Grande Fracture{/link}, des cités des elfes se dressaient le long de sa côte ouest, et la cité de {link:the-zoram-strand}Zoram{/link} dominait la mer. Quand le {link:well-of-eternity}puits d'Éternité{/link} fut détruit, la mer monta et engloutit Zoram, et les ruines des anciens temples restèrent éparpillées dans les bois : {link:the-ruins-of-ordil-aran}Ordil'Aran{/link}, le {link:bathran-s-haunt}Repaire de Bathran{/link}, les {link:the-ruins-of-stardust}ruines de Chimétoile{/link} et la cité de {link:xavian}Xavian{/link} à l'est. Après la guerre, les elfes de la nuit s'établirent à l'ombre du {link:mount-hyjal}mont Hyjal{/link} et se vouèrent aux voies de {link:cenarius}Cenarius{/link} et des druides. Tandis que les druides dormaient dans le {link:emerald-dream}Rêve d'émeraude{/link}, les {link:sentinels}Sentinelles{/link} de {link:tyrande-whisperwind}Tyrande Whisperwind{/link} veillèrent sur la forêt au long des âges de la Longue Veille. Aucune chronique ne dit quand {link:astranaar}Astranaar{/link} et les autres villages de la forêt furent élevés.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Orneval n'a pas connu la paix depuis la {link:third-war}Troisième Guerre{/link}. Les {link:sentinels}Sentinelles{/link} tiennent {link:astranaar}Astranaar{/link}, le {link:maestra-s-post}Poste de Maestra{/link}, le {link:silverwind-refuge}Refuge de Vent-argent{/link} et le {link:forest-song}Chant des forêts{/link}, mais leurs rangs sont clairsemés et leurs routes longues. Les furbolgs {link:thistlefur-village}Crins-de-Chardon{/link} et Foulweald, autrefois amis des elfes, ont été empoisonnés par une corruption qui descend de {link:felwood}Gangrebois{/link}, et ils se jettent sur tous les voyageurs. Des satyres tiennent le {link:night-run}Défilé de la nuit{/link}, {link:satyrnaar}Satyrnaar{/link} et {link:xavian}Xavian{/link}. Les {link:naga}nagas{/link} sont revenus dans les ruines englouties de {link:the-zoram-strand}Zoram{/link}, et un culte du {link:twilight-s-hammer}Marteau du crépuscule{/link} se rassemble dans les salles inondées des {link:blackfathom-deeps}Profondeurs de Brassenoire{/link}. À l'est, les orcs Warsong coupent du bois pour la {link:horde}Horde{/link} sous la garde du {link:splintertree-post}Poste de Bois-brisé{/link}. Sur la côte ouest, ils ont élevé un second avant-poste, {link:zoram-gar-outpost}Zoram'gar{/link}. Les elfes répondent à chaque arbre abattu par des flèches, et chaque saison, la guerre entre les deux peuples s'étend un peu plus loin dans les bois.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les elfes de la nuit.{/b} {link:sentinels}Sentinelles{/link}, druides et prêtresses qui tiennent les villages de la forêt et se battent pour la garder intacte.
• {b}Les dryades.{/b} Les filles de {link:cenarius}Cenarius{/link} dansent encore dans les clairières de la {link:raynewood-retreat}Retraite de Raynewood{/link} et du {link:the-shrine-of-aessina}sanctuaire d'Aessina{/link}.
• {b}La {link:horde}Horde{/link}.{/b} Les orcs Warsong, avec à leurs côtés des trolls, des taurens et des gobelins, tiennent le {link:splintertree-post}Poste de Bois-brisé{/link}, les camps de bûcherons de l'est et l'{link:zoram-gar-outpost}Avant-poste de Zoram'gar{/link} sur la côte.
• {b}Les {link:forsaken}Réprouvés{/link}.{/b} Des apothicaires d'{link:undercity}Undercity{/link} se sont glissés dans les refuges et les ruines des elfes.
• {b}Les furbolgs.{/b} Les {link:thistlefur-village}Crins-de-Chardon{/link} du nord et les Foulweald du sud, rendus fous, et les {link:bloodtooth-camp}Dent-rouge{/link}, qui suivent un roi sauvage.
• {b}Les satyres.{/b} Les satyres Felmusk, Bleakheart et de {link:xavian}Xavian{/link} vénèrent des démons dans les temples en ruine de l'est.
• {b}Les nagas.{/b} Les nagas Wrathtail hantent la {link:the-zoram-strand}grève de Zoram{/link} et les eaux de {link:blackfathom-deeps}Brassenoire{/link}.
• {b}Les démons.{/b} Des gangregardes et des infernaux rôdent encore dans le canyon où tomba {link:mannoroth}Mannoroth{/link}.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La cité engloutie.{/b} Lors de la {link:great-sundering}Fracture{/link}, la mer prit {link:the-zoram-strand}Zoram{/link}. Ses souverains, son anneau et ses secrets sombrèrent avec elle.
• {b}La Longue Veille.{/b} Pendant dix mille ans, les {link:sentinels}Sentinelles{/link} gardèrent Orneval tandis que les druides dormaient, et la forêt devint profonde et silencieuse.
• {b}L'arrivée des orcs.{/b} Pendant la {link:third-war}Troisième Guerre{/link}, les orcs de {link:grom-hellscream}Grom Hellscream{/link} vinrent à Orneval couper du bois pour leur nouveau foyer. Les Sentinelles ripostèrent, et {link:cenarius}Cenarius{/link} lui-même se leva pour défendre la forêt. Grom et ses guerriers burent à une source souillée par le sang de {link:mannoroth}Mannoroth{/link}, et dans cette fureur, ils tuèrent le demi-dieu. Ensuite, dans un canyon de la forêt orientale, Grom tua Mannoroth et libéra son peuple de la malédiction du sang, mais il mourut de ses blessures.
• {b}Hyjal.{/b} Lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, elfes, orcs et humains se dressèrent ensemble contre {link:archimonde}Archimonde{/link}, et la Légion fut brisée. L'alliance de ce jour-là ne survécut pas à la victoire.
• {b}Aujourd'hui.{/b} La {link:horde}Horde{/link} coupe toujours les arbres d'Orneval. Les elfes de la nuit ne l'ont jamais accepté.]=],
		},
		{
			title = "Légendes de la forêt",
			text = [=[• Le Tome de {link:the-howling-vale}Mel'Thandris{/link}, conservé dans un sanctuaire en ruine près de la frontière de {link:felwood}Gangrebois{/link}, consignerait de lui-même les événements importants sur ses pages. Personne ne comprend comment.
• Un {link:furbolgs}furbolg{/link} nommé {link:krolg}Krolg{/link} vit seul près du {link:mystral-lake}Lac Mystral{/link}. Il ne parle qu'aux siens, et il accuse les elfes de la ruine de son peuple.
• Les chasseurs de {link:splintertree-post}Bois-brisé{/link} parlent de trois grandes bêtes de la forêt : l'ours {link:ursangous}Ursangous{/link}, le sabre-de-nuit {link:shadumbra}Shadumbra{/link} et l'hippogriffe {link:sharptalon}Sharptalon{/link}. Les abattre toutes les trois est une épreuve de la valeur de tout chasseur.
• Les satyres ont volé le Rameau de {link:cenarius}Cenarius{/link} aux dryades, et les dryades ne l'ont pas pardonné.]=],
		},
	},
})

Translate("frFR", "astranaar", {
	title = "Astranaar",
	sections = {
		{
			title = "Résumé",
			text = [=[Astranaar est la principale ville des elfes de la nuit en {link:ashenvale}Orneval{/link}. Elle se dresse sur une île, au milieu d'un lac au cœur de la forêt, reliée à la rive par des ponts de pierre blanche. Ici, {link:raene-wolfrunner}Raene Wolfrunner{/link} commande les {link:sentinels}Sentinelles{/link} de la région, et d'ici, des éclaireurs partent vers chaque recoin de la forêt. La ville a une auberge, un perchoir d'hippogriffes et un petit marché d'artisans elfes. Elle est aussi devenue une maison d'inquiétude. Ses sentinelles signalent que les furbolgs se multiplient au nord, un enfant est malade dans l'une de ses demeures, et la guerre avec la {link:horde}Horde{/link} se rapproche de ses ponts à chaque saison.]=],
		},
	},
})

Translate("frFR", "maestra-s-post", {
	title = "Poste de Maestra",
	aliases = { "Maestra" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Poste de Maestra est un petit avant-poste elfe au nord-ouest d'{link:ashenvale}Orneval{/link}, sur la route qui descend de {link:darkshore}Sombrivage{/link}. C'est le premier abri qu'un voyageur venu d'{link:auberdine}Auberdine{/link} trouve dans la forêt. Des {link:sentinels}Sentinelles{/link} y montent la garde, et le druide {link:orendil-broadleaf}Orendil Broadleaf{/link} y prépare ses remèdes. Un paladin humain, {link:delgren-the-purifier}Delgren le Purificateur{/link}, en a fait sa base dans sa guerre contre le {link:cult-of-the-dark-strand}Cult of the Dark Strand{/link}, et ses messagers portent des provisions au nord, jusqu'à Auberdine. Les druides tout juste éveillés du {link:emerald-dream}Rêve d'émeraude{/link} sont envoyés ici pour y être accueillis.]=],
		},
	},
})

Translate("frFR", "bathran-s-haunt", {
	title = "Repaire de Bathran",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Repaire de Bathran est une ruine elfe dans les collines du nord d'{link:ashenvale}Orneval{/link}, juste au sud de la frontière de {link:darkshore}Sombrivage{/link}. Une plante appelée cheveux de Bathran poussait autrefois parmi ses pierres, et les druides la prisaient comme remède contre les maladies de l'esprit. La ruine n'est plus déserte. Des {link:forsaken}Réprouvés{/link} ont établi un camp entre ses murs, et leurs herboristes récoltent ce qui y pousse à des fins qui leur sont propres. Les druides du {link:maestra-s-post}Poste de Maestra{/link} trouvent leur présence très inquiétante.]=],
		},
	},
})

Translate("frFR", "the-ruins-of-ordil-aran", {
	title = "Les Ruines d'Ordil'Aran",
	aliases = { "Ordil'Aran" },
	sections = {
		{
			title = "Résumé",
			text = [=[Ordil'Aran est une ville en ruine des anciens elfes, au nord d'{link:ashenvale}Orneval{/link}, au nord-est du {link:maestra-s-post}Poste de Maestra{/link}. Son nom rappelle les villes jumelles d'{link:ameth-aran}Ameth’Aran{/link} et de {link:bashal-aran}Bashal'Aran{/link}, en {link:darkshore}Sombrivage{/link}, qui furent bâties pour les Bien-nés au temps de la {link:queen-azshara}reine Azshara{/link}. Désormais, les démonistes du {link:cult-of-the-dark-strand}Cult of the Dark Strand{/link} fouillent parmi ses pierres. L'un d'eux portait une gemme d'âme qui renfermait le secret de la puissance du culte, jusqu'à ce que {link:delgren-the-purifier}Delgren le Purificateur{/link} envoie un champion la prendre.]=],
		},
	},
})

Translate("frFR", "the-zoram-strand", {
	title = "La grève de Zoram",
	aliases = { "grève de Zoram", "Zoram" },
	sections = {
		{
			title = "Résumé",
			text = [=[La grève de Zoram est la côte ouest d'{link:ashenvale}Orneval{/link}, un rivage de sable gris et de colonnes brisées. Sous les vagues se trouve Zoram, une cité des elfes que la mer engloutit lors de la {link:great-sundering}Grande Fracture{/link}. Pendant des âges, elle fut presque oubliée. Désormais, les {link:naga}nagas{/link} y sont revenus, et nul ne sait ce qu'ils cherchent. Les nagas Wrathtail, avec des hydres à leurs côtés, tiennent le rivage et ses îles. À l'extrémité nord de la grève, un grand temple à demi englouti par la mer ouvre sur les profondeurs des {link:blackfathom-deeps}Profondeurs de Brassenoire{/link}.]=],
		},
	},
})

Translate("frFR", "zoram-gar-outpost", {
	title = "Avant-poste de Zoram'gar",
	aliases = { "Zoram'gar" },
	sections = {
		{
			title = "Résumé",
			text = [=[Zoram'gar est l'avant-poste de la {link:horde}Horde{/link} sur la {link:the-zoram-strand}grève de Zoram{/link}, un camp d'orcs et de trolls sur une langue de terre au bord de la mer. Il fut bâti pour revendiquer la côte ouest d'{link:ashenvale}Orneval{/link} au nom de la Horde, et pour surveiller les nagas et les ruines de {link:blackfathom-deeps}Brassenoire{/link}. {link:karang-amakkar}Karang Amakkar{/link} le commande. Le troll {link:je-neu-sancrea}Je'neu Sancrea{/link}, du {link:earthen-ring}Cercle terrestre{/link}, étudie la mer depuis son rivage. Le camp est durement pressé. Les nagas l'attaquent, une grande hydre l'a assailli plus d'une fois, et les furbolgs {link:thistlefur-village}Crins-de-Chardon{/link} se tiennent entre lui et le {link:splintertree-post}Poste de Bois-brisé{/link}.]=],
		},
	},
})

Translate("frFR", "lake-falathim", {
	title = "Lac Falathim",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Lac Falathim s'étend au pied des montagnes de l'ouest d'{link:ashenvale}Orneval{/link}. Sur son île se dressait un sanctuaire où les elfes gardaient autrefois une gemme lumineuse, jusqu'à ce que le sanctuaire soit envahi. Les {link:murlocs}murlocs{/link} de la tribu Saltspittle tiennent désormais la rive. C'est ici que l'elfe {link:teronis}Teronis{/link} vint chercher la gemme, et ici que ses amis trouvèrent son corps, lacéré par des griffes de murlocs, étendu intact sur l'île.]=],
		},
	},
})

Translate("frFR", "the-shrine-of-aessina", {
	title = "Le sanctuaire d'Aessina",
	aliases = { "sanctuaire d'Aessina", "Aessina" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le sanctuaire d'Aessina est une clairière cachée dans les montagnes de l'ouest d'{link:ashenvale}Orneval{/link}, enclose de falaises et accessible par peu de sentiers. En son sein se dresse un sanctuaire d'une grande et subtile puissance, où se rassemble la magie de la forêt. Des dryades y demeurent, parmi lesquelles {link:therysil}Therysil{/link} et {link:illiyana}Illiyana{/link}, et la sentinelle {link:sentinel-melyria-frostshadow}Melyria Frostshadow{/link} veille sur {link:moonglade}la clairière{/link}. Ceux qui cherchent à renouveler un enchantement viennent déposer leur ouvrage dans son bassin, et attendent la lueur.]=],
		},
	},
})

Translate("frFR", "fire-scar-shrine", {
	title = "Sanctuaire de Scarfeu",
	aliases = { "Scarfeu" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Sanctuaire de Scarfeu est un lieu de grand mal au sud-ouest d'{link:ashenvale}Orneval{/link}. Son sol est brûlé et ses arbres sont morts. Ici, le démoniste {link:orcs}orc{/link} {link:ilkrud-magthrull}Ilkrud Magthrull{/link} a son repaire, et des démons répondent à son appel. Un démon appelé Akkrilus marche parmi les cendres. Les elfes tenaient autrefois Ilkrud pour une simple nuisance. Cela changea quand {link:delgren-the-purifier}Delgren le Purificateur{/link} apprit que le démoniste prenait des notes sur les plans du {link:cult-of-the-dark-strand}Cult of the Dark Strand{/link}.]=],
		},
	},
})

Translate("frFR", "thistlefur-village", {
	title = "Village des Crins-de-Chardon",
	aliases = { "Antre des Crins-de-Chardon", "Crins-de-Chardon" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Village des Crins-de-Chardon est le foyer des {link:furbolgs}furbolgs{/link} Crins-de-Chardon, au nord d'{link:astranaar}Astranaar{/link}. Leurs huttes s'étendent à travers les bois, et au bout du village, une grotte appelée l'antre des Crins-de-Chardon s'enfonce dans la colline. Les Crins-de-Chardon n'ont pas toujours été des ennemis, mais ils sont corrompus désormais, et leur nombre a beaucoup augmenté ces derniers mois. Les {link:sentinels}Sentinelles{/link} craignent qu'ils ne deviennent assez audacieux pour attaquer Astranaar elle-même. La {link:horde}Horde{/link} les craint aussi, car le village bloque la route entre {link:zoram-gar-outpost}Zoram'gar{/link} et {link:splintertree-post}Bois-brisé{/link}.]=],
		},
	},
})

Translate("frFR", "iris-lake", {
	title = "Lac Iris",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Lac Iris s'étend à l'est d'{link:astranaar}Astranaar{/link}, une eau paisible avec un îlot en son cœur. Sur cet îlot repose une pierre appelée Larme d'Elune, que l'on ne trouve nulle part ailleurs au monde. Les druides disent qu'elle peut laver la corruption. Quand la fille de {link:pelturas-whitemoon}Pelturas Whitemoon{/link} était malade et tourmentée de cauchemars, c'est la Larme du Lac Iris qui les apaisa.]=],
		},
	},
})

Translate("frFR", "the-ruins-of-stardust", {
	title = "Les ruines de Chimétoile",
	aliases = { "ruines de Chimétoile" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les ruines de Chimétoile se trouvent au sud d'{link:astranaar}Astranaar{/link}, parmi les arbres de la forêt méridionale. Il n'y reste guère que des pierres brisées. Pourtant, une poussière givrée s'amasse parmi les ruines, et les druides savent qu'elle peut faire tomber une fièvre. Le nom du lieu est plus ancien que toute archive, et les elfes disent seulement qu'il fut nommé d'après la poussière.]=],
		},
	},
})

Translate("frFR", "mystral-lake", {
	title = "Lac Mystral",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Lac Mystral est une vaste étendue d'eau au sud d'{link:ashenvale}Orneval{/link}, près de l'entrée de la {link:the-talondeep-path}Perce des Serres{/link} qui mène aux {link:stonetalon-mountains}Serres-Rocheuses{/link}. Ses eaux se sont animées. Des élémentaires souillés en surgissent et attaquent tout ce qui s'approche, et la route entre la forêt et les Serres-Rocheuses est presque fermée. Un belvédère sur le lac donne sur le refuge elfe de la rive, et les {link:sentinels}Sentinelles{/link} comme la {link:horde}Horde{/link} s'intéressent à qui observe depuis là. Sur la rive sud vit {link:krolg}Krolg{/link}, un {link:furbolgs}furbolg{/link} qui a échappé à la corruption des siens.]=],
		},
	},
})

Translate("frFR", "silverwind-refuge", {
	title = "Refuge de Vent-argent",
	aliases = { "Vent-argent" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Refuge de Vent-argent est un village des elfes de la nuit sur la rive sud du {link:mystral-lake}Lac Mystral{/link}. Il a ses propres marchands, maîtres et alchimistes, et un perchoir d'hippogriffes. La sentinelle {link:sentinel-velene-starstrike}Velene Starstrike{/link} commande sa garde. Ces derniers temps, le refuge n'a connu aucun repos, car le lac voisin se remplit d'élémentaires souillés. Velene a appris qui les crée, et elle a juré qu'il paierait.]=],
		},
	},
})

Translate("frFR", "fallen-sky-lake", {
	title = "Lac Tombeciel",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Lac Tombeciel s'étend au sud-est d'{link:ashenvale}Orneval{/link}. Les elfes ramassaient autrefois des pierres de lune le long de sa rive, des pierres tombées du ciel qui portent la force de la lune. Puis vinrent les Shadethicket. Ce sont des tréants corrompus, et leur oracle a rassemblé chaque pierre de lune tombée dans son propre trésor. Les elfes ne vont plus au lac.]=],
		},
	},
})

Translate("frFR", "raynewood-retreat", {
	title = "Retraite de Raynewood",
	aliases = { "Raynewood" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Retraite de Raynewood est un bosquet en hauteur au cœur d'{link:ashenvale}Orneval{/link}, couronné par un grand arbre du même nom. Des dryades appelées les Sœurs rieuses jouent dans ses clairières, et des guerriers cénariens gardent ses sentiers. Au sommet de l'arbre demeure le gardien {link:keeper-ordanus}Ordanus{/link}, un fils de {link:cenarius}Cenarius{/link}, qui fut emmené ici en secret depuis les cimes des {link:stonetalon-mountains}Serres-Rocheuses{/link} quand un démoniste du {link:shadow-council}Conseil des ombres{/link} chercha à lui prendre la vie. Des cerfs et de grands ours parcourent les pentes en contrebas, et le sabre-de-nuit {link:shadumbra}Shadumbra{/link} chasse parmi eux.]=],
		},
	},
})

Translate("frFR", "the-howling-vale", {
	title = "Le Val hurlant",
	aliases = { "Val hurlant", "Mel'Thandris" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Val hurlant se trouve au nord d'{link:ashenvale}Orneval{/link}, près de la frontière de {link:felwood}Gangrebois{/link}. Son cœur est le sanctuaire en ruine de Mel'Thandris, où l'on conserve un étrange tome. Mel'Thandris elle-même bénit ses pages, et par un pouvoir que nul ne peut expliquer, elles consignent les grands événements du pays. Depuis peu, des hommes-loups ont pris le sanctuaire. Leurs appels glaçants ont donné son nom au val. Le tome a montré aux {link:sentinels}Sentinelles{/link} que ces créatures sont liées à une prêtresse disparue, et à une relique appelée la {red:scythe-of-elune}Faux d'Elune{/red}.]=],
		},
	},
})

Translate("frFR", "night-run", {
	title = "Défilé de la nuit",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Défilé de la nuit est une vallée tenue par les satyres au nord-est d'{link:ashenvale}Orneval{/link}. Ses temples sont imprégnés de sang, et même des guerriers aguerris les trouvent troublants. Ici, le seigneur bien-né {link:athrikus-narassin}Athrikus Narassin{/link} cacha l'une de ses dernières gemmes d'âme, et l'âme captive d'un Bien-né y attendit jusqu'à ce qu'elle soit libérée. Les satyres du Défilé de la nuit détiennent aussi de l'huile volée aux Warsong, qu'ils brûlent lors de leurs rituels.]=],
		},
	},
})

Translate("frFR", "satyrnaar", {
	title = "Satyrnaar",
	sections = {
		{
			title = "Résumé",
			text = [=[Satyrnaar est la place forte des satyres Felmusk dans l'est d'{link:ashenvale}Orneval{/link}, une ruine enveloppée d'ombre gangrenée. C'est l'un des lieux où {link:athrikus-narassin}Athrikus Narassin{/link} gardait une gemme d'âme, et où l'âme d'un Bien-né était emprisonnée. Comme le {link:night-run}Défilé de la nuit{/link} et {link:xavian}Xavian{/link}, ce fut autrefois un temple. Le paladin {link:delgren-the-purifier}Delgren le Purificateur{/link} a entendu dire que l'histoire des satyres est liée à celle des elfes de la nuit, mais ses hôtes refusent d'en parler.]=],
		},
	},
})

Translate("frFR", "xavian", {
	title = "Xavian",
	sections = {
		{
			title = "Résumé",
			text = [=[Xavian est une cité légendaire des anciens elfes, nichée dans les collines de l'est d'{link:ashenvale}Orneval{/link}. Les érudits parlent de son savoir perdu, et l'on dit que les eaux de sa plus haute cascade renferment une grande magie. Les satyres de Xavian règnent désormais sur ses ruines, avec parmi eux des voleurs, des gangrelliés et des invocateurs infernaux. Leur maître, {link:geltharis}Geltharis{/link}, vola le Rameau de {link:cenarius}Cenarius{/link} aux dryades. Trois sœurs dryades entrèrent dans Xavian pour le reprendre. Une seule en ressortit vivante, et pas pour longtemps.]=],
		},
	},
})

Translate("frFR", "forest-song", {
	title = "Chant des forêts",
	aliases = { "Bois de Chantenuit" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Chant des forêts est un sanctuaire des elfes de la nuit dans le Bois de Chantenuit, à l'est d'{link:ashenvale}Orneval{/link}, près de la frontière d'{link:azshara}Azshara{/link}. Le druide {link:kayneth-stillwind}Kayneth Stillwind{/link} en a la garde. D'ici, il lit les rapports des {link:sentinels}Sentinelles{/link} et y cherche les signes d'une malfaisance qu'il craint de voir se répandre dans la forêt. Le sanctuaire se dresse près des camps de bûcherons de la {link:horde}Horde{/link} et des ruines satyres de {link:xavian}Xavian{/link}, et ses druides dorment rarement en paix.]=],
		},
	},
})

Translate("frFR", "bough-shadow", {
	title = "L'Ombrage",
	sections = {
		{
			title = "Résumé",
			text = [=[L'Ombrage est un grand arbre situé à l'extrême nord-est d'{link:ashenvale}Orneval{/link}, au-delà du {link:forest-song}Chant des forêts{/link}. C'est l'un des quatre arbres dont les druides disent qu'ils sont des portes vers le {link:emerald-dream}Rêve d'émeraude{/link}. Des dragonnides verts montent la garde à son pied, et de grands drakes verts tournoient autour de sa cime. Ils ne souffrent personne à proximité, et les elfes du Chant des forêts les laissent en paix.]=],
		},
	},
})

Translate("frFR", "splintertree-post", {
	title = "Poste de Bois-brisé",
	aliases = { "Bois-brisé" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Poste de Bois-brisé est la place forte de la {link:horde}Horde{/link} à l'est d'{link:ashenvale}Orneval{/link}, un camp fortifié de huttes orques sur une colline au-dessus de la route des {link:the-barrens}Tarides{/link}. Il protège les camps de bûcherons Warsong et les routes qui emportent leur bois vers le sud. Ses guerriers, chasseurs et marchands viennent de tous les peuples de la Horde. {link:mastok-wrilehiss}Mastok Wrilehiss{/link} grogne à sa porte, {link:senani-thunderheart}Senani Thunderheart{/link} soumet les jeunes chasseurs à leurs épreuves, et {link:ertog-ragetusk}Ertog Ragetusk{/link} prépare les raids contre les elfes. Peu de nuits s'y passent sans alerte.]=],
		},
	},
})

Translate("frFR", "warsong-lumber-camp", {
	title = "Camp de bûcherons Warsong",
	aliases = { "Camp de travail Warsong" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Camp de bûcherons Warsong se trouve à l'extrême est d'{link:ashenvale}Orneval{/link}, près du fleuve qui sépare la forêt d'{link:azshara}Azshara{/link}. Ici, les péons du clan Warsong abattent les grands arbres des elfes et envoient le bois vers le sud pour bâtir et alimenter la {link:horde}Horde{/link}. Des déchiqueteuses gobelines rugissent parmi les souches, et des grunts protègent les ouvriers des flèches des {link:sentinels}Sentinelles{/link}. C'est ce labeur qui amena {link:grom-hellscream}Grom Hellscream{/link} à Orneval pendant la {link:third-war}Troisième Guerre{/link}, et il ne s'est jamais arrêté. Le camp vit de ses approvisionnements : des lames de scie de {link:ratchet}Ratchet{/link}, des haches de {link:booty-bay}Baie-du-Butin{/link}, de l'huile et de la corde que les satyres et les furbolgs ne cessent de voler.]=],
		},
	},
})

Translate("frFR", "demon-fall-canyon", {
	title = "Canyon de la Malechute",
	aliases = { "Crête de la Malechute", "Malechute", "Colline Gangrefeu" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Canyon de la Malechute est une gorge profonde au sud-est d'{link:ashenvale}Orneval{/link}, et son nom rappelle le plus célèbre haut fait de la {link:third-war}Troisième Guerre{/link}. Dans un canyon de cette forêt, {link:grom-hellscream}Grom Hellscream{/link} planta sa hache dans le seigneur des fosses {link:mannoroth}Mannoroth{/link} et libéra les orcs du sang du démon, et c'est là qu'il mourut. Le canyon n'a pas été purifié. Des gangregardes y montent la garde, des infernaux couvent parmi ses rochers, et des chiens de la Légion chassent sur la crête au-dessus. Sur la Colline Gangrefeu, au sud, un seigneur de l'effroi appelé Diathorus le Chercheur les commande.]=],
		},
	},
})

Translate("frFR", "the-dor-danil-barrow-den", {
	title = "Le Refuge des saisons de Dor'danil",
	aliases = { "Refuge des saisons de Dor'danil", "Dor'danil" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Refuge des saisons de Dor'danil se trouve au sud-est d'{link:ashenvale}Orneval{/link}, à l'est de la route des {link:the-barrens}Tarides{/link}. Ses druides y dormaient autrefois et gardaient un fragment d'un ancien sceptre. Puis les {link:forsaken}Réprouvés{/link} arrivèrent. Ils bâtirent un camp à côté du refuge, préparèrent leurs maladies et empoisonnèrent les druides dans leur sommeil. Les esprits des druides de Dor'danil se relevèrent, arrachés à leurs corps et rendus fous, et ils errent désormais dans le refuge avec les morts-vivants qui les ont tués.]=],
		},
	},
})

Translate("frFR", "silverwing-outpost", {
	title = "Avant-poste d'Aile-argent",
	aliases = { "Bosquet d'Aile-argent" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'Avant-poste d'Aile-argent est un camp des {link:sentinels}Sentinelles{/link} au sud d'{link:ashenvale}Orneval{/link}, établi parmi les arbres à l'ouest des routes forestières de la {link:horde}Horde{/link}. Ses éclaireuses se glissent à travers les bois pour espionner les orcs, et ses guerriers se tiennent prêts à frapper {link:splintertree-post}Bois-brisé{/link}. {link:duriel-moonfire}Duriel Moonfire{/link} le dirige. La Horde le tient pour une dague plantée dans son flanc, et ses pillards ont juré de le prendre.]=],
		},
	},
})

Translate("frFR", "bloodtooth-camp", {
	title = "Camp de Dent-rouge",
	aliases = { "Dent-rouge" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Camp de Dent-rouge est le repaire du {link:furbolgs}furbolg{/link} {link:ran-bloodtooth}Ran Bloodtooth{/link} et de ses gardes, au sud d'{link:ashenvale}Orneval{/link}, près de la lisière des {link:the-barrens}Tarides{/link}. Ran est le plus féroce des furbolgs corrompus, un roi parmi les siens, et la corruption n'a fait que le rendre plus fort. Même les autres furbolgs craignent ce qui sort de ce camp.]=],
		},
	},
})

Translate("frFR", "greenpaw-village", {
	title = "Village des Pattes-vertes",
	aliases = { "Tertre totémique des Foulweald" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Village des Pattes-vertes est le foyer des furbolgs Foulweald, au sud de la route à l'est d'{link:astranaar}Astranaar{/link} et à l'ouest du Fleuve Falfarren. En son cœur se dresse le tertre totémique de la tribu. Les Foulweald sont moins nombreux que les {link:thistlefur-village}Crins-de-Chardon{/link}, mais plus féroces, et ils attaquent les voyageurs sur la route. Les {link:sentinels}Sentinelles{/link} comme la {link:horde}Horde{/link} les ont frappés. Quand une bannière de la Horde fut plantée sur leur tertre, leur chef sortit défendre l'honneur de sa tribu, et tomba.]=],
		},
	},
})

Translate("frFR", "raene-wolfrunner", {
	title = "Raene Wolfrunner",
	subtitle = "Commandante des Sentinelles d'Astranaar",
	found = "Astranaar, à côté de ses deux bêtes",
	hint = [=[Parlez à la chasseresse qui commande les Sentinelles d'Astranaar.]=],
	allegiance = "Sentinelles · Darnassus",
	aliases = { "Raene" },
	sections = {
		{
			title = "Résumé",
			text = [=[Raene Wolfrunner dirige les {link:sentinels}Sentinelles{/link} d'{link:astranaar}Astranaar{/link}. C'est une chasseresse qui garde à ses côtés un loup et un grand félin, et chaque rapport venu de la forêt passe entre ses mains. Elle fait appel à de l'aide jusqu'en {link:darkshore}Sombrivage{/link}, et ceux qui répondent la trouvent calme, grave et très à court de guerriers.]=],
		},
		{
			title = "Importance",
			text = [=[Raene tient le cœur d'{link:ashenvale}Orneval{/link} pour les elfes de la nuit en un temps où leurs ennemis les pressent de tous côtés. Sa guerre se livre sur deux fronts à la fois : contre la {link:horde}Horde{/link}, et contre la corruption qui a changé les furbolgs de la forêt en bêtes.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle envoie des éclaireurs et des volontaires contre les {link:thistlefur-village}Crins-de-Chardon{/link} et les Foulweald.
• Elle reprit le travail de son ami {link:teronis}Teronis{/link} après sa mort.
• Elle garde le crâne d'un roi {link:furbolgs}furbolg{/link} et un ancien sceptre à une place d'honneur, à {link:astranaar}Astranaar{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La mort de Teronis",
			hint = [=[Cherchez des nouvelles de l'ami perdu de Raene sur une île à l'ouest.]=],
			text = [=[{link:teronis}Teronis{/link}, l'ami de Raene, partit à l'ouest vers le {link:lake-falathim}Lac Falathim{/link} à la recherche d'une gemme, et il ne revint pas. Il traquait les fragments d'un sceptre fabriqué par un sorcier mort, Dartol, qui selon lui pouvait freiner les attaques des furbolgs. Son corps fut retrouvé sur l'île, lacéré par des griffes de murlocs. Raene mit son chagrin de côté. Le temps du deuil viendrait plus tard. Ce qui comptait à présent, c'était que son travail ne soit pas perdu.]=],
		},
		{
			title = "Le sceptre de Dartol",
			hint = [=[Rassemblez les fragments du sceptre et cherchez la dryade au puits de lune.]=],
			text = [=[D'après les notes du journal de {link:teronis}Teronis{/link}, on retrouva les fragments du sceptre de Dartol à travers la forêt : l'un gardé par des tréants corrompus près de {link:felwood}Gangrebois{/link}, un autre caché avec les druides condamnés de {link:the-dor-danil-barrow-den}Dor'danil{/link}. La dryade {link:shael-dryn}Shael'dryn{/link} les assembla, et un sanctuaire caché rendit au sceptre sa puissance. Il pouvait prêter à son porteur l'apparence d'un {link:furbolgs}furbolg{/link}. Raene ne savait pas ce que Teronis avait voulu en faire. Elle devinait qu'il espérait parler à un furbolg encore épargné par la gangremousse.]=],
		},
		{
			title = "Le crâne de Ran Bloodtooth",
			hint = "Apprenez ce que le furbolg non corrompu demande aux siens.",
			text = [=[Le sceptre mena à {link:krolg}Krolg{/link}, un {link:furbolgs}furbolg{/link} qui avait échappé à la corruption, et qui accusait les elfes de tout ce qui était arrivé à son peuple. Pourtant, Krolg ne voulait pas que des enfants elfes en souffrent. Il demanda que les siens fassent eux-mêmes justice parmi eux, et c'est ainsi que {link:ran-bloodtooth}Ran Bloodtooth{/link}, le plus féroce des furbolgs corrompus, fut tué. Raene plaça son crâne et le sceptre de Dartol là où tout {link:astranaar}Astranaar{/link} pouvait les voir, et dit que {link:teronis}Teronis{/link} serait fier.]=],
		},
	},
	mentions = {
		{ text = "Expédition vers {link:ashenvale}Orneval{/link}" },
		{ text = "Une défense agressive" },
		{ text = "Éliminer la menace" },
		{ text = "La purification de Raene" },
	},
	bonds = {
		{ id = "teronis", name = "Teronis", note = "son ami, dont elle acheva le travail" },
		{ id = "shael-dryn", name = "Shael'dryn", note = "aida à refaire le sceptre de Dartol" },
		{ id = "krolg", name = "Krolg", note = "le furbolg qui servit sa cause" },
		{ id = "ran-bloodtooth", name = "Ran Bloodtooth", note = "ennemi" },
		{ id = "dal-bloodclaw", name = "Dal Bloodclaw", note = "ennemi" },
		{ id = "sentinel-thenysil", name = "Sentinelle Thenysil", note = "une Sentinelle sous ses ordres" },
	},
})

Translate("frFR", "teronis", {
	title = "Teronis",
	subtitle = "Chercheur du sceptre de Dartol",
	found = "L'île du Lac Falathim",
