		{ text = "La purification de {link:raene-wolfrunner}Raene{/link}" },
	},
	bonds = {
		{ id = "raene-wolfrunner", name = "Raene Wolfrunner", note = "son amie" },
	},
})

Translate("frFR", "shael-dryn", {
	title = "Shael'dryn",
	subtitle = "Dryade du puits de lune",
	found = [=[Un puits de lune au nord de la route de l'est, à l'est du Lac Iris]=],
