		{ text = "La purification de {link:raene-wolfrunner}Raene{/link}" },
		{ text = "La purification de {link:raene-wolfrunner}Raene{/link}" },
		{ text = "La purification de {link:raene-wolfrunner}Raene{/link}" },
		{ text = "La purification de {link:raene-wolfrunner}Raene{/link}" },
	},
	bonds = {
		{ id = "raene-wolfrunner", name = "Raene Wolfrunner", note = "lui envoya les chercheurs du sceptre" },
	},
})

Translate("frFR", "krolg", {
	title = "Krolg",
	subtitle = "Le furbolg non corrompu",
	found = "Une hutte isolée au sud du Lac Mystral",
	hint = "Trouvez le furbolg qui vit seul au sud du Lac Mystral.",
	allegiance = "Furbolgs",
	sections = {
		{
			title = "Résumé",
			text = [=[Krolg est un {link:furbolgs}furbolg{/link} qui a échappé à la gangremousse et à sa corruption. Il fut chassé de sa tribu, et il vit seul. Il ne parle qu'aux siens. Krolg accuse les elfes de la nuit de ce qui est arrivé aux furbolgs, et sa haine est brûlante. Pourtant, il est juste. Il ne veut pas voir des enfants elfes souffrir, et il estime que les furbolgs doivent répondre de leurs propres maux. C'est pourquoi il demanda que {link:ran-bloodtooth}Ran Bloodtooth{/link} soit tué.]=],
