	},
	mentions = {
		{ text = "La purification de {link:raene-wolfrunner}Raene{/link}" },
		{ text = "La purification de {link:raene-wolfrunner}Raene{/link}" },
	},
	bonds = {
		{ id = "ran-bloodtooth", name = "Ran Bloodtooth", note = "le mal auquel il voulait mettre fin" },
		{ id = "raene-wolfrunner", name = "Raene Wolfrunner", note = "une alliée sans le savoir" },
