})

Translate("frFR", "ran-bloodtooth", {
	title = "Ran Bloodtooth",
	subtitle = "Roi des Dent-rouge",
	found = "Camp de Dent-rouge, au sud d'Orneval",
	hint = [=[Méfiez-vous du seigneur furbolg dont le camp se trouve près de la lisière sud de la forêt.]=],
	allegiance = "Furbolgs",
	sections = {
		{
			title = "Résumé",
			text = [=[Ran Bloodtooth est le plus redouté des furbolgs corrompus d'{link:ashenvale}Orneval{/link}. Il était avide de pouvoir avant même que la corruption ne le touche, et la corruption n'a fait que le rendre plus fort. Son esprit ne lui appartient plus. Sa haine brûle plus fort encore que celle de {link:krolg}Krolg{/link}, et il est une menace pour toutes les créatures de la forêt. Les {link:sentinels}Sentinelles{/link} le désignèrent comme la plus féroce menace {link:furbolgs}furbolg{/link} d'Orneval. Son crâne repose désormais à une place d'honneur, à {link:astranaar}Astranaar{/link}.]=],
		},
	},
	mentions = {
		{ text = "La purification de {link:raene-wolfrunner}Raene{/link}" },
		{ text = "La purification de {link:raene-wolfrunner}Raene{/link}" },
	},
	bonds = {
		{ id = "krolg", name = "Krolg", note = "voulait sa mort" },
		{ id = "raene-wolfrunner", name = "Raene Wolfrunner", note = "garde son crâne" },
	},
})

Translate("frFR", "dal-bloodclaw", {
	title = "Dal Bloodclaw",
	subtitle = "Chef des Crins-de-Chardon",
	found = "Village des Crins-de-Chardon, au nord d'Astranaar",
	hint = "Cherchez le chef des furbolgs au nord d'Astranaar.",
	allegiance = "Furbolgs · Crins-de-Chardon",
	sections = {
		{
			title = "Résumé",
