Translate("frFR", "pelturas-whitemoon", {
	title = "Pelturas Whitemoon",
	subtitle = "Père de Relara",
	found = "Astranaar, au chevet de sa fille",
	hint = "Trouvez le père d'Astranaar dont l'enfant est malade.",
	allegiance = "Elfes de la nuit",
	aliases = { "Pelturas" },
	sections = {
		{
			title = "Résumé",
			text = [=[Pelturas Whitemoon est un {link:night-elves}elfe de la nuit{/link} d'{link:astranaar}Astranaar{/link} dont la fille, Relara, tomba gravement malade. Son mal était plus qu'un mal du corps. Elle était tourmentée de cauchemars, brûlait de fièvre et s'affaiblissait d'heure en heure. Le druide {link:orendil-broadleaf}Orendil Broadleaf{/link} lui envoya un remède et lui parla d'autres traitements si celui-ci échouait. Pelturas les suivit tous.]=],
		},
	},
	chapters = {
		{
			title = "La guérison de Relara",
			hint = [=[Rassemblez les remèdes d'Orendil pour l'enfant malade d'Astranaar.]=],
			text = [=[Le premier remède ne fit que ralentir le mal. La Larme d'Elune, venue de l'îlot du {link:iris-lake}Lac Iris{/link}, chassa les cauchemars. La poussière givrée des {link:the-ruins-of-stardust}ruines de Chimétoile{/link} fit tomber la fièvre. Enfin, une pierre de lune tombée, arrachée au trésor de l'oracle Shadethicket, rendit à Relara ses forces. Pelturas offrit en remerciement son bien le plus cher.]=],
		},
	},
	mentions = {
		{ text = "Le remède d'{link:orendil-broadleaf}Orendil{/link}" },
		{ text = "La Larme d'Elune" },
		{ text = "{link:the-ruins-of-stardust}Les ruines de Chimétoile{/link}" },
	},
	bonds = {
		{ id = "orendil-broadleaf", name = "Orendil Broadleaf", note = "envoya les remèdes" },
	},
})

