Translate("frFR", "kayneth-stillwind", {
	title = "Kayneth Stillwind",
	subtitle = "Druide du Chant des forêts",
	found = "Chant des forêts",
	hint = [=[Cherchez le druide qui garde le sanctuaire du Chant des forêts, à l'est.]=],
	allegiance = "Elfes de la nuit",
	aliases = { "Kayneth" },
	sections = {
		{
			title = "Résumé",
			text = [=[Kayneth Stillwind garde le sanctuaire du {link:forest-song}Chant des forêts{/link}. Il craint qu'une malfaisance ne parcoure {link:ashenvale}Orneval{/link}, et il lit chaque rapport des {link:sentinels}Sentinelles{/link} pour en trouver les signes. Il en trouva un chez les {link:forsaken}Réprouvés{/link}, qui s'étaient glissés dans les refuges des elfes. Tandis qu'il examinait leurs poisons, il eut une vision : les druides de {link:the-dor-danil-barrow-den}Dor'danil{/link}, assassinés dans leur sommeil et relevés en fantômes rendus fous. Il demanda que leurs chefs soient détruits pour que les autres trouvent la paix. Il sentit l'angoisse s'apaiser quand ce fut fait.]=],
		},
	},
	chapters = {
		{
			title = "Les druides de Dor'danil",
			hint = "Apprenez ce que les Réprouvés préparent à côté du refuge.",
			text = [=[Les {link:forsaken}Réprouvés{/link} avaient un camp près du {link:the-dor-danil-barrow-den}Refuge des saisons de Dor'danil{/link}, où ils mettaient en bouteille poisons et maladies. Kayneth croyait qu'ils voulaient répandre la maladie sur les terres des elfes. Il avait raison, et c'était pire. Les druides du refuge avaient été empoisonnés, et Taneel Darkwood, Uthil Mooncall et Mavoris Cloudsbreak, autrefois leurs chefs, menaient désormais une foule d'esprits rendus fous. Kayneth qualifia leur fin de sinistre besogne, car ils n'étaient que des victimes.]=],
		},
	},
	mentions = {
		{ text = "Kayneth Stillwind" },
		{ text = "Esprit ancien" },
	},
	bonds = {
		{ id = "shindrell-swiftfire", name = "Shindrell Swiftfire", note = "lui envoie des rapports" },
	},
})

