Translate("frFR", "senani-thunderheart", {
	title = "Senani Thunderheart",
	subtitle = "Maîtresse de la chasse d'Orneval",
	found = "Poste de Bois-brisé",
	hint = [=[Parlez à la taurène qui soumet les chasseurs de Bois-brisé à leur épreuve.]=],
	allegiance = "Horde · Taurens",
	aliases = { "Senani" },
	sections = {
		{
			title = "Résumé",
			text = [=[Senani Thunderheart est une taurène du {link:splintertree-post}Poste de Bois-brisé{/link} qui perpétue la tradition de la chasse d'{link:ashenvale}Orneval{/link}. Trois bêtes légendaires parcourent la forêt : l'ours {link:ursangous}Ursangous{/link}, le sabre-de-nuit {link:shadumbra}Shadumbra{/link} et l'hippogriffe {link:sharptalon}Sharptalon{/link}. Elle envoie les jeunes chasseurs de la {link:horde}Horde{/link} à leur poursuite, afin qu'ils mettent leur ruse à l'épreuve et apprennent quelque chose sur eux-mêmes. Elle semble sentir qui arrive avant même qu'ils ne soient là.]=],
		},
	},
	chapters = {
		{
			title = "La chasse d'Orneval",
			hint = "Abattez les trois grandes bêtes de la forêt.",
			text = [=[{link:ursangous}Ursangous{/link} avait tué beaucoup de monde, et un croissant sur sa patte montrait que les elfes de la nuit l'avaient dressé. {link:shadumbra}Shadumbra{/link} avait rendu mortelle chaque route vers l'ouest, jusqu'à la {link:the-zoram-strand}grève de Zoram{/link}. {link:sharptalon}Sharptalon{/link} terrorisait depuis longtemps les péons des camps de bûcherons. Quand les trois furent tombés, Senani proclama le chasseur qui les avait tués digne enfant des ancêtres.]=],
		},
	},
	mentions = {
		{ text = "La chasse d'{link:ashenvale}Orneval{/link}" },
		{ text = "La patte d'{link:ursangous}Ursangous{/link}" },
		{ text = "La tête de {link:shadumbra}Shadumbra{/link}" },
		{ text = "La serre de {link:sharptalon}Sharptalon{/link}" },
	},
	bonds = {
		{ id = "ursangous", name = "Ursangous", note = "l'une des trois bêtes" },
		{ id = "shadumbra", name = "Shadumbra", note = "l'une des trois bêtes" },
		{ id = "sharptalon", name = "Sharptalon", note = "l'une des trois bêtes" },
	},
})

