Translate("frFR", "je-neu-sancrea", {
	title = "Je'neu Sancrea",
	subtitle = "Chaman du Cercle terrestre",
	found = "Avant-poste de Zoram'gar, au bord de la mer",
	hint = [=[Parlez au troll du Cercle terrestre qui observe les vagues à Zoram'gar.]=],
	allegiance = "Cercle terrestre · Horde",
	aliases = { "Je'neu" },
	sections = {
		{
			title = "Résumé",
			text = [=[Je'neu Sancrea est un chaman troll du {link:earthen-ring}Cercle terrestre{/link} qui demeure à l'{link:zoram-gar-outpost}Avant-poste de Zoram'gar{/link}. Il étudie l'eau et tous les éléments avec une telle attention qu'il remarque souvent à peine les gens qui l'entourent. Il vint sur la {link:the-zoram-strand}grève de Zoram{/link} sur l'ordre du Cercle terrestre, car quelque chose sous la mer retourne les éléments contre le monde.]=],
		},
		{
			title = "Importance",
			text = [=[Je'neu est la sentinelle de la {link:horde}Horde{/link} au-dessus des {link:blackfathom-deeps}Profondeurs de Brassenoire{/link}. Par lui, le {link:earthen-ring}Cercle terrestre{/link} apprit que le {link:twilight-s-hammer}Marteau du crépuscule{/link} était venu au temple englouti, et qu'il comptait éveiller des puissances que les chamans espéraient disparues à jamais.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il étudia le globe souillé du {link:mystral-lake}Lac Mystral{/link}.
• Il apprit le nom de {link:lorgus-jett}Lorgus Jett{/link} et réclama sa mort.
• Il rechercha un noyau des profondeurs qui consigne toute activité élémentaire dans les ruines.
• Il étudia le globe qui nourrissait l'élémentaire corrompu baron {link:baron-aquanis}Aquanis{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Les saphirs d'Aku'Mai",
			hint = [=[Apprenez pourquoi les nagas récoltent des cristaux dans les tunnels de Brassenoire.]=],
			text = [=[Dans les premiers tunnels des {link:blackfathom-deeps}Profondeurs de Brassenoire{/link}, de grands amas de saphirs poussent sur les parois, et les esprits de l'eau s'y accrochent. Les nagas avaient commencé à les récolter. Je'neu ne savait pas pourquoi, mais il craignait que les cristaux ne deviennent une arme puissante entre de mauvaises mains. Il les fit prendre avant que les nagas ne puissent s'en servir.]=],
		},
		{
			title = "Allégeance aux Dieux très anciens",
			hint = "Suivez la note humide trouvée dans les profondeurs.",
			text = [=[Une note froissée révéla le reste. Les prêtresses nagas devaient apporter les cristaux à un homme nommé {link:lorgus-jett}Lorgus Jett{/link}, qui comptait se servir de leur puissance pour plaire à un être appelé {link:aku-mai}Aku'Mai{/link} et le rappeler dans le monde. Il rêvait d'un nouvel âge gouverné par les Dieux très anciens. Lorgus appartenait au {link:twilight-s-hammer}Marteau du crépuscule{/link}. Je'neu était trop faible pour l'affronter, et il envoya d'autres dans les profondeurs pour en finir avec lui.]=],
		},
		{
			title = "Le noyau des profondeurs",
			hint = "Cherchez la pierre qui se souvient des éléments.",
			text = [=[Le {link:twilight-s-hammer}Marteau du crépuscule{/link} avait pris les ruines du Sanctuaire de la lune, dans les profondeurs. Je'neu demanda le noyau des profondeurs qui reposait dans la pierre des profondeurs des ruines, un objet qui garde la trace de chaque mouvement des éléments. Avec lui, et avec l'étrange globe qui avait nourri le baron {link:baron-aquanis}Aquanis{/link} corrompu, le {link:earthen-ring}Cercle terrestre{/link} pourrait commencer à comprendre ce que faisait le culte, et comment.]=],
		},
	},
	mentions = {
		{ text = "Je'neu du {link:earthen-ring}Cercle terrestre{/link}" },
		{ text = "Des ennuis dans les profondeurs" },
	},
	bonds = {
		{ id = "mastok-wrilehiss", name = "Mastok Wrilehiss", note = "lui envoya le globe" },
		{ id = "tideress", name = "Tideress", note = "l'esprit souillé qu'il étudia" },
		{ id = "karang-amakkar", name = "Karang Amakkar", note = "commande son avant-poste" },
	},
})

