Translate("frFR", "mitsuwa", {
	title = "Mitsuwa",
	subtitle = "De Zoram'gar",
	found = "Avant-poste de Zoram'gar",
	hint = "Parlez à la trollesse de Zoram'gar qui pleure les siens.",
	allegiance = "Horde · Trolls",
	sections = {
		{
			title = "Résumé",
			text = [=[Mitsuwa est une trollesse de {link:zoram-gar-outpost}Zoram'gar{/link}. Les siens se rendaient à l'avant-poste avec des charmes trolls sacrés quand les furbolgs {link:thistlefur-village}Crins-de-Chardon{/link} tombèrent sur eux et les tuèrent tous. Elle les pleure, et elle croit qu'elle les retrouvera dans l'au-delà. Mais les charmes appartiennent à ce monde, et elle enrage que des furbolgs les gardent dans les coffres de l'antre des Crins-de-Chardon. Un troll sans son charme, dit-elle, ne vaut rien.]=],
		},
	},
